import{_ as a,o as t,c as n,ao as i}from"./chunks/framework.DMEKwIGU.js";const u=JSON.parse('{"title":"Backends and fallbacks","description":"","frontmatter":{},"headers":[],"relativePath":"manual/backend.md","filePath":"manual/backend.md","lastUpdated":null}'),o={name:"manual/backend.md"};function s(r,e,l,d,p,c){return t(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="Backends-and-fallbacks" tabindex="-1">Backends and fallbacks <a class="header-anchor" href="#Backends-and-fallbacks" aria-label="Permalink to &quot;Backends and fallbacks {#Backends-and-fallbacks}&quot;">​</a></h1><h2 id="Call-flow" tabindex="-1">Call flow <a class="header-anchor" href="#Call-flow" aria-label="Permalink to &quot;Call flow {#Call-flow}&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Julia Matrix / Vector and LinearAlgebra</span></span>
<span class="line"><span>                  ↓</span></span>
<span class="line"><span>           libblastrampoline</span></span>
<span class="line"><span>                  ↓</span></span>
<span class="line"><span>        BLAS ABI of libcolmat_blas</span></span>
<span class="line"><span>                  ↓</span></span>
<span class="line"><span>       Rust colmat / Rust compatibility layer</span></span></code></pre></div><p><code>Colmat.__init__()</code> runs <code>Colmat.load_backend()</code>. It checks that the library exists and the compatibility layer&#39;s ABI version, then registers ILP64 and LP64, in that order, with <code>BLAS.lbt_forward</code>.</p><p>Rust borrows Julia arrays only for the duration of the call. No Rust matrix ownership or lifetime-management handle is exposed on the Julia side. Mutation rules such as those of <code>mul!</code> follow the Julia API.</p><h2 id="Handling-unsupported-routines" tabindex="-1">Handling unsupported routines <a class="header-anchor" href="#Handling-unsupported-routines" aria-label="Permalink to &quot;Handling unsupported routines {#Handling-unsupported-routines}&quot;">​</a></h2><p>Registration uses <code>clear=false</code>. It replaces the symbols Colmat provides and retains the forwarding targets of unsupported BLAS / LAPACK routines.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Call</th><th style="text-align:right;">Where it runs</th></tr></thead><tbody><tr><td style="text-align:right;">GEMM / GEMV and similar for supported types</td><td style="text-align:right;">Colmat</td></tr><tr><td style="text-align:right;">Band/packed storage or unsupported BLAS</td><td style="text-align:right;">The existing forwarding target</td></tr><tr><td style="text-align:right;">LAPACK LU / SVD / general and self-adjoint eigenvalues / Cholesky</td><td style="text-align:right;">Colmat</td></tr><tr><td style="text-align:right;">LAPACK such as QR / Schur / generalized eigenvalues that is not connected yet</td><td style="text-align:right;">The existing forwarding target</td></tr><tr><td style="text-align:right;">Types outside this BLAS, such as integers or BigFloat</td><td style="text-align:right;">Julia&#39;s existing per-type implementation</td></tr></tbody></table><p>Whether BLAS calls made from inside the fallback&#39;s shared library go through LBT depends on that library&#39;s link configuration. Having an entry registered in LBT is not the same as switching the internal computations of other unconnected factorizations to Colmat. Loading this package alone also does not replace the choice of sparse solver.</p><h2 id="Scope-and-ordering-of-switching" tabindex="-1">Scope and ordering of switching <a class="header-anchor" href="#Scope-and-ordering-of-switching" aria-label="Permalink to &quot;Scope and ordering of switching {#Scope-and-ordering-of-switching}&quot;">​</a></h2><p>Changes apply to the whole Julia process and also affect other packages that go through LBT. They are not per-computation, per-array, or per-Julia-Task settings.</p><p>Loading another BLAS provider later may cause that provider to change the forwarding targets. To re-select Colmat, run:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Colmat</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">load_backend</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span></code></pre></div><p>This call also retains the current forwarding targets of unsupported routines. It does not restore an original OpenBLAS configuration or pin the fallback to a specific library.</p><p>Finish switching backends before starting parallel BLAS computation. Colmat&#39;s internal configuration lock does not synchronize other packages or direct LBT operations.</p><h2 id="LAPACK-conversion-and-unsupported-options" tabindex="-1">LAPACK conversion and unsupported options <a class="header-anchor" href="#LAPACK-conversion-and-unsupported-options" aria-label="Permalink to &quot;LAPACK conversion and unsupported options {#LAPACK-conversion-and-unsupported-options}&quot;">​</a></h2><p>Colmat converts the final LU permutation to LAPACK&#39;s IPIV and the SVD&#39;s V to VT. The LU and Cholesky factorizations borrow the caller&#39;s array and run in place, and SVD, general/self-adjoint EVD, Schur/QZ, generalized Hessenberg, and least squares also read their input without copying it. Workspace queries accept LAPACK&#39;s <code>lwork=-1</code> and similar forms, but the native workspace is currently allocated inside the adapter. This is not an implementation that runs without allocation using only the LAPACK work array.</p><p>General EVD uses native balancing, left/right eigenvector computation, and Schur computation. It currently performs additional work to obtain the returned Schur form, so there is a performance limitation.</p><p>For GEEVX, <code>SENSE=N</code> is native, and condition estimation for <code>SENSE=E/V/B</code> uses the saved original implementation. An implementation with the same integer ABI is preferred; if there is no original LP64 GEEVX, integers are converted and the call is delegated to the saved ILP64 implementation. All four types require an ILP64 GEEVX before Colmat is loaded. If it is missing, initialization stops with a configuration error before LBT is changed. A valid expert mode is not reported as an invalid <code>SENSE</code>. Re-running <code>load_backend()</code> does not save Colmat itself as an original backend and retains the existing implementation.</p><p>GGEV/GGEV3/GEGV and GGEVX with <code>BALANC=N/SENSE=N</code> use native GEVD. Other balance/condition modes of GGEVX are delegated to the saved ILP64 backend, with integer conversion for LP64 calls. Therefore all four types require an ILP64 GGEVX before Colmat is loaded. Ordinary Julia provides OpenBLAS. If it is missing, initialization stops with a configuration error before changing the LBT registration.</p><p>SYEVR/HEEVR compute the full spectrum and then select the <code>RANGE=A/I/V</code> results. This does not mean colmat-rs has a public MRRR or Sturm-count API. Per-driver numerical implementations, storage formats, and unsupported features are documented in <a href="/Colmat.jl/dev/reference/lbt-inventory#Full-LBT-and-colmat-rs-routine-mapping">Full LBT and colmat-rs routine mapping</a>.</p>`,21)])])}const g=a(o,[["render",s]]);export{u as __pageData,g as default};
